urrentColor\" stroke-width=\"2\" stroke-linecap=\"round\">\n            <line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\" />\n            <line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\" />\n          </svg>\n        </button>\n\n        <!-- 图片区域：点击查看原图 -->\n        <div class=\"lightbox-img-container\" @click=\"openOriginal\">\n          <img :src=\"entry.img\" :alt=\"entry.name\" class=\"lightbox-img\" />\n          <div class=\"lightbox-img-hint\">\n            <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <circle cx=\"11\" cy=\"11\" r=\"8\" />\n              <line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\" />\n              <line x1=\"11\" y1=\"8\" x2=\"11\" y2=\"14\" />\n              <line x1=\"8\" y1=\"11\" x2=\"14\" y2=\"11\" />\n            </svg>\n            <span>查看原图</span>\n          </div>\n        </div>\n\n        <!-- 信息 -->\n        <div class=\"lightbox-info\">\n          <div class=\"lightbox-id\">{{ entry.id }}</div>\n          <div class=\"lightbox-name\">{{ entry.name }}</div>\n          <div class=\"lightbox-desc\">{{ entry.desc }}</div>\n        </div>\n\n        <!-- 导航 -->\n        <div class=\"lightbox-nav\">\n          <button\n            class=\"lightbox-nav-btn\"\n            :disabled=\"!hasPrev\"\n            @click=\"$emit('prev')\"\n          >\n            <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <polyline points=\"15 18 9 12 15 6\" />\n            </svg>\n          </button>\n          <button\n            class=\"lightbox-nav-btn\"\n            :disabled=\"!hasNext\"\n            @click=\"$emit('next')\"\n          >\n            <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <polyline points=\"9 18 15 12 9 6\" />\n            </svg>\n          </button>\n        </div>\n      </div>\n    </div>\n  </Transition>\n</template>\n\n<script setup lang=\"ts\">\nimport type { AchievementEntry } from '../achievements';\n\nconst props = defineProps<{\n  entry: AchievementEntry | null;\n  hasPrev: boolean;\n  hasNext: boolean;\n}>();\n\ndefineEmits<{\n  close: [];\n  prev: [];\n  next: [];\n}>();\n\nfunction openOriginal() {\n  if (props.entry?.img) {\n    window.parent.open(props.entry.img, '_blank');\n  }\n}\n</script>\n\n<style scoped>\n.lightbox-overlay {\n  position: fixed;\n  left: 0;\n  top: 0;\n  width: 100vw;\n  height: 100vh;\n  background: rgba(0, 0, 0, 0.85);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  z-index: 10000;\n  backdrop-filter: blur(4px);\n  pointer-events: auto;\n  padding: 16px;\n  box-sizing: border-box;\n}\n\n.lightbox-card {\n  position: relative;\n  max-width: 420px;\n  width: 100%;\n  max-height: calc(100vh - 32px);\n  overflow-y: auto;\n  background: rgba(12, 18, 30, 0.98);\n  border-radius: 12px;\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);\n  margin: auto;\n}\n\n.lightbox-close {\n  position: absolute;\n  top: 10px;\n  right: 10px;\n  z-index: 2;\n  width: 28px;\n  height: 28px;\n  border-radius: 50%;\n  border: none;\n  background: rgba(0, 0, 0, 0.5);\n  color: rgba(255, 255, 255, 0.7);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background 0.2s;\n}\n\n.lightbox-close:hover {\n  background: rgba(0, 0, 0, 0.7);\n  color: #fff;\n}\n\n.lightbox-img-container {\n  position: relative;\n  width: 100%;\n  aspect-ratio: 1;\n  overflow: hidden;\n  background: rgba(0, 0, 0, 0.3);\n  cursor: zoom-in;\n}\n\n.lightbox-img-container:hover .lightbox-img-hint {\n  opacity: 1;\n}\n\n.lightbox-img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  display: block;\n  transition: transform 0.3s ease;\n}\n\n.lightbox-img-container:hover .lightbox-img {\n  transform: scale(1.03);\n}\n\n.lightbox-img-hint {\n  position: absolute;\n  bottom: 8px;\n  right: 8px;\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  padding: 4px 10px;\n  border-radius: 12px;\n  background: rgba(0, 0, 0, 0.6);\n  color: rgba(255, 255, 255, 0.8);\n  font-size: 11px;\n  opacity: 0;\n  transition: opacity 0.2s ease;\n  pointer-events: none;\n}\n\n.lightbox-info {\n  padding: 16px 18px;\n}\n\n.lightbox-id {\n  font-size: 10px;\n  color: rgba(255, 255, 255, 0.3);\n  font-family: monospace;\n  margin-bottom: 4px;\n}\n\n.lightbox-name {\n  font-size: 16px;\n  font-weight: 600;\n  color: rgba(255, 255, 255, 0.9);\n  margin-bottom: 6px;\n}\n\n.lightbox-desc {\n  font-size: 12px;\n  color: rgba(255, 255, 255, 0.5);\n  line-height: 1.5;\n}\n\n.lightbox-nav {\n  display: flex;\n  justify-content: center;\n  gap: 16px;\n  padding: 0 18px 16px;\n}\n\n.lightbox-nav-btn {\n  width: 32px;\n  height: 32px;\n  border-radius: 50%;\n  border: 1px solid rgba(255, 255, 255, 0.1);\n  background: rgba(255, 255, 255, 0.04);\n  color: rgba(255, 255, 255, 0.6);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: all 0.2s;\n}\n\n.lightbox-nav-btn:hover:not(:disabled) {\n  background: rgba(255, 255, 255, 0.08);\n  color: #fff;\n}\n\n.lightbox-nav-btn:disabled {\n  opacity: 0.25;\n  cursor: default;\n}\n\n/* 手机端适配：图片区域不使用 1:1，改为更小的比例 */\n@media (max-width: 500px) {\n  .lightbox-overlay {\n    padding: 8px;\n  }\n\n  .lightbox-card {\n    max-width: 100%;\n    border-radius: 10px;\n  }\n\n  .lightbox-img-container {\n    aspect-ratio: 4 / 3;\n  }\n\n  .lightbox-info {\n    padding: 12px 14px;\n  }\n\n  .lightbox-name {\n    font-size: 14px;\n    margin-bottom: 4px;\n  }\n\n  .lightbox-desc {\n    font-size: 11px;\n  }\n\n  .lightbox-nav {\n    padding: 0 14px 12px;\n    gap: 24px;\n  }\n\n  .lightbox-nav-btn {\n    width: 36px;\n    height: 36px;\n  }\n\n  /* 手机端始终显示查看原图提示 */\n  .lightbox-img-hint {\n    opacity: 0.7;\n  }\n}\n\n/* 过渡动画 */\n.lightbox-enter-active,\n.lightbox-leave-active {\n  transition: opacity 0.25s ease;\n}\n\n.lightbox-enter-active .lightbox-card,\n.lightbox-leave-active .lightbox-card {\n  transition: transform 0.25s ease;\n}\n\n.lightbox-enter-from,\n.lightbox-leave-to {\n  opacity: 0;\n}\n\n.lightbox-enter-from .lightbox-card {\n  transform: scale(0.9);\n}\n\n.lightbox-leave-to .lightbox-card {\n  transform: scale(0.9);\n}\n</style>\n"],"sourceRoot":""}]);
