`, "",{"version":3,"sources":["webpack://./src/洛潮汐成就相册/components/ProgressRing.vue"],"names":[],"mappings":"AAuFA,gCACE,aACF","sourcesContent":["<template>\n  <svg :width=\"size\" :height=\"size\" :viewBox=\"`0 0 ${size} ${size}`\" class=\"progress-ring\">\n    <!-- 背景圈 -->\n    <circle\n      :cx=\"center\"\n      :cy=\"center\"\n      :r=\"radius\"\n      fill=\"none\"\n      :stroke=\"trackColor\"\n      :stroke-width=\"strokeWidth\"\n    />\n    <!-- 进度圈 -->\n    <circle\n      :cx=\"center\"\n      :cy=\"center\"\n      :r=\"radius\"\n      fill=\"none\"\n      :stroke=\"progressColor\"\n      :stroke-width=\"strokeWidth\"\n      stroke-linecap=\"round\"\n      :stroke-dasharray=\"circumference\"\n      :stroke-dashoffset=\"dashOffset\"\n      :style=\"{ transition: 'stroke-dashoffset 0.6s ease, stroke 0.6s ease' }\"\n      transform-origin=\"center\"\n      :transform=\"`rotate(-90 ${center} ${center})`\"\n    />\n    <!-- 中间文字 -->\n    <text\n      :x=\"center\"\n      :y=\"center - 4\"\n      text-anchor=\"middle\"\n      dominant-baseline=\"central\"\n      :fill=\"textColor\"\n      :font-size=\"fontSize\"\n      font-weight=\"600\"\n      font-family=\"'Segoe UI', system-ui, sans-serif\"\n    >\n      {{ unlocked }}\n    </text>\n    <text\n      :x=\"center\"\n      :y=\"center + 10\"\n      text-anchor=\"middle\"\n      dominant-baseline=\"central\"\n      :fill=\"subTextColor\"\n      :font-size=\"subFontSize\"\n      font-family=\"'Segoe UI', system-ui, sans-serif\"\n    >\n      / {{ total }}\n    </text>\n  </svg>\n</template>\n\n<script setup lang=\"ts\">\nconst props = withDefaults(defineProps<{\n  size?: number;\n  strokeWidth?: number;\n  percent: number;\n  unlocked: number;\n  total: number;\n}>(), {\n  size: 52,\n  strokeWidth: 3,\n});\n\nconst center = computed(() => props.size / 2);\nconst radius = computed(() => (props.size - props.strokeWidth * 2) / 2);\nconst circumference = computed(() => 2 * Math.PI * radius.value);\nconst dashOffset = computed(() => circumference.value * (1 - props.percent / 100));\n\nconst trackColor = 'rgba(255, 255, 255, 0.12)';\nconst subTextColor = 'rgba(255, 255, 255, 0.45)';\nconst textColor = 'rgba(255, 255, 255, 0.9)';\nconst fontSize = computed(() => props.size > 48 ? 13 : 10);\nconst subFontSize = computed(() => props.size > 48 ? 9 : 7);\n\nconst progressColor = computed(() => {\n  const p = props.percent;\n  if (p >= 100) return '#e8c56d';\n  if (p >= 75) return '#c4a35a';\n  if (p >= 50) return '#7eb8c9';\n  if (p >= 25) return '#5a9bb5';\n  return '#4a7d91';\n});\n</script>\n\n<style scoped>\n.progress-ring {\n  display: block;\n}\n</style>\n"],"sourceRoot":""}]);
