locked\">\n            <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"rgba(255,255,255,0.2)\" stroke-width=\"1.5\">\n              <rect x=\"3\" y=\"11\" width=\"18\" height=\"11\" rx=\"2\" />\n              <path d=\"M7 11V7a5 5 0 0110 0v4\" />\n            </svg>\n          </div>\n        </div>\n        <div class=\"grid-label\">\n          {{ isUnlocked(entry.id) ? entry.name : '???' }}\n        </div></div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { CHAPTERS, ACHIEVEMENT_MAP, type AchievementEntry } from '../achievements';\n\nconst props = defineProps<{\n  activeChapter: string;\n  progress: { unlocked: number; total: number } | undefined;\n  isUnlocked: (id: string) => boolean;\n  isMobile?: boolean;\n}>();\n\nconst emit = defineEmits<{\n  view: [id: string];\n}>();\n\nconst currentChapter = computed(() => CHAPTERS.find(c => c.prefix === props.activeChapter));\nconst entries = computed<AchievementEntry[]>(() => ACHIEVEMENT_MAP[props.activeChapter] || []);\n\nfunction handleClick(id: string) {\n  if (props.isUnlocked(id)) {\n    emit('view', id);\n  }\n}\n</script>\n\n<style scoped>\n.grid-container {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  background: rgba(8, 14, 25, 0.35);\n  backdrop-filter: blur(4px);\n}\n\n.grid-header {\n  padding: 14px 18px 10px;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.06);\n  display: flex;\n  align-items: baseline;\n  gap: 10px;\n  flex-shrink: 0;\n}\n\n.grid-chapter-name {\n  font-size: 14px;\n  font-weight: 600;\n  color: rgba(255, 255, 255, 0.85);\n}\n\n.grid-chapter-progress {\n  font-size: 11px;\n  color: rgba(255, 255, 255, 0.35);\n}\n\n.grid-content {\n  flex: 1;\n  overflow-y: auto;\n  padding: 12px 14px;\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(90px, 1fr));\n  gap: 10px;\n  align-content: start;\n}\n\n/* 手机端: 更小的网格 */\n.grid-content.is-mobile {\n  padding: 8px 8px;\n  grid-template-columns: repeat(auto-fill, minmax(70px, 1fr));\n  gap: 8px;\n}\n\n.grid-content::-webkit-scrollbar {\n  width: 4px;\n}\n\n.grid-content::-webkit-scrollbar-thumb {\n  background: rgba(255, 255, 255, 0.08);\n  border-radius: 2px;\n}\n\n.grid-item {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  cursor: pointer;\n  transition: transform 0.2s;\n}\n\n.grid-item.unlocked:hover {\n  transform: scale(1.05);\n}\n\n.grid-item.locked {\n  cursor: default;\n  opacity: 0.5;\n}\n\n.grid-img-wrap {\n  width: 80px;\n  height: 80px;\n  border-radius: 6px;\n  overflow: hidden;\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  background: rgba(255, 255, 255, 0.02);\n}\n\n/* 手机端: 缩小图片容器 */\n.is-mobile .grid-img-wrap {\n  width: 64px;\n  height: 64px;\n  border-radius: 5px;\n}\n\n.grid-item.unlocked .grid-img-wrap {\n  border-color: rgba(90, 155, 181, 0.3);\n  box-shadow: 0 0 8px rgba(90, 155, 181, 0.1);\n}\n\n.grid-img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  display: block;\n}\n\n.grid-locked {\n  width: 100%;\n  height: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background: rgba(15, 20, 30, 0.8);\n}\n\n.is-mobile .grid-locked svg {\n  width: 16px;\n  height: 16px;\n}\n\n.grid-label {\n  margin-top: 4px;\n  font-size: 10px;\n  color: rgba(255, 255, 255, 0.5);\n  text-align: center;\n  max-width: 80px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n/* 手机端: 标签适配 */\n.is-mobile .grid-label {\n  font-size: 9px;max-width: 64px;\n}\n\n.grid-item.unlocked .grid-label {\n  color: rgba(255, 255, 255, 0.75);\n}\n</style>\n"],"sourceRoot":""}]);
